import { Component, OnInit, inject, ChangeDetectorRef } from '@angular/core';
import { CommonModule, NgIf, NgFor } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { AdminService } from '../../../core/services/admin.service';
import { environment } from '../../../../environments/environment';

@Component({
  selector: 'app-manage-users',
  standalone: true,
  imports: [CommonModule, NgIf, NgFor, FormsModule],
  templateUrl: './manage-users.component.html',
  styleUrls: ['./manage-users.component.css']
})

export class ManageUsersComponent implements OnInit {
  private adminService = inject(AdminService);
  private cdr = inject(ChangeDetectorRef);
  readonly assetsUrl = environment.assetsUrl;

  usersList: any[] = [];
  isLoading = false;
  searchTerm = '';
  selectedUser: any = null;
  showUserCard = false;
  isUserEditMode = false;
  userEditData: any = {};

  get filteredUsers(): any[] {
    if (!this.searchTerm || !this.searchTerm.trim()) {
      return this.usersList;
    }
    const q = this.searchTerm.toLowerCase();
    return this.usersList.filter(user =>
      (user.name || '').toLowerCase().includes(q) ||
      (user.email || '').toLowerCase().includes(q) ||
      (user.role || '').toLowerCase().includes(q)
    );
  }

  ngOnInit(): void {
    this.isLoading = true;
    this.adminService.getAllUsers().subscribe({
      next: (data) => {
        this.usersList = data;
        this.isLoading = false;
        this.cdr.detectChanges();
      },
      error: () => this.isLoading = false
    });
  }

   // ... votre code actuel et votre fonction onDeleteUser ...

  onDeleteUser(userId: number): void {
    if (confirm("⚠️ Êtes-vous sûr de vouloir supprimer définitivement cet utilisateur de Tun-Job ?")) {
      this.adminService.deleteUser(userId).subscribe({
        next: () => {
          this.usersList = this.usersList.filter(u => u.id !== userId);
          this.cdr.detectChanges();
        }
      });
    }
  }

  openUserCard(user: any): void {
    this.selectedUser = { ...user };
    this.userEditData = { ...user };
    this.isUserEditMode = false;
    this.showUserCard = true;
  }

  closeUserCard(): void {
    this.showUserCard = false;
    this.selectedUser = null;
  }

  toggleUserEditMode(mode: boolean): void {
    this.isUserEditMode = mode;
    if (!mode) {
      this.userEditData = { ...this.selectedUser };
    }
  }

  getUserRoleLabel(user: any): string {
    return user?.role === 'recruiter' ? 'Recruteur' : 'Candidat';
  }

  getVerificationLabel(user: any): string {
    if (user?.role === 'recruiter') {
      return user.is_verified_company ? 'Entreprise certifiée' : 'Certification en attente';
    }
    return user.is_verified ? 'Compte vérifié' : 'Compte non vérifié';
  }

  // 👑 COLLEZ LE CODE JUSTE ICI, AVANT LA DERNIÈRE ACCOLADE DE FERMETURE :
  onToggleVerification(user: any): void {
    const nextStatus = user.is_verified_company ? 0 : 1;
    this.adminService.toggleCompanyVerification(user.id, nextStatus).subscribe({
      next: () => {
        user.is_verified_company = nextStatus; // Met à jour l'interface instantanément
        this.cdr.detectChanges();
      }
    });
  }

  onSaveUserEdit(): void {
    this.adminService.updateUser(this.userEditData.id, this.userEditData).subscribe({
      next: (res: any) => {
        const updatedUser = res.user || res;
        const index = this.usersList.findIndex(u => u.id === updatedUser.id);
        if (index !== -1) {
          this.usersList[index] = { ...updatedUser };
        }
        this.selectedUser = { ...updatedUser };
        this.isUserEditMode = false;
        this.cdr.detectChanges();
        alert("Profil utilisateur mis à jour !");
      },
      error: (err: any) => alert("Erreur : " + (err.error?.message || "Impossible de mettre à jour."))
    });
  }

} // 👈 Cette accolade ferme toute votre classe, laissez-la bien tout en bas
 
<div class="manage-container">
  <div class="card-header-flex">
    <div class="card-header-left">
      <h3><i class="bi bi-person-gear"></i> Gestion des Utilisateurs</h3>
      <p>Consultez la liste des membres inscrits et modérez les accès à la plateforme.</p>
    </div>
  </div>

  <div class="manage-card-premium">
    <div class="admin-search-bar">
      <input type="text" placeholder="Rechercher utilisateur par nom, email ou rôle..." [(ngModel)]="searchTerm" />
    </div>
    <div class="table-wrapper-premium">
      
      <div *ngIf="isLoading" class="loading-box">
        <i class="bi bi-arrow-clockwise spinning"></i> Chargement des comptes utilisateurs...
      </div>

      <table *ngIf="!isLoading" class="jobs-table-premium">
        <thead>
          <tr>
            <th class="th-left-padding">Nom / Rôle</th>
            <th>Adresse E-mail</th>
            <th>Statut du compte</th>
            <th class="th-center-align">Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let user of filteredUsers" class="table-row-premium">
            <td class="job-company-cell">
              <span class="clickable-job-title" style="font-size: 14px !important; font-weight: 700;" (click)="openUserCard(user)">{{ user.name }}</span>
              <span class="company-sub-badge">
                <i class="bi" [ngClass]="user.role === 'recruiter' ? 'bi-building' : 'bi-person'"></i> 
                {{ user.role === 'recruiter' ? 'Recruteur' : 'Candidat' }}
              </span>
            </td>
            <td class="date-text-cell-premium">{{ user.email }}</td>
            <td>
              <span class="status-badge-fixed" [ngClass]="user.is_verified ? 'bg-emerald' : 'bg-amber'">
                <span class="dot-status"></span>
                <span class="badge-text-span">{{ user.is_verified ? 'Vérifié' : 'En attente' }}</span>
              </span>
            </td>
                        <td class="status-cell-premium" style="display: flex; gap: 8px; justify-content: center;">
              
              <!-- 👑 Bouton Certifier : S'affiche UNIQUEMENT pour les recruteurs -->
              <button *ngIf="user.role === 'recruiter'" 
                      [style.background-color]="user.is_verified_company ? '#e0f2fe' : '#f1f5f9'"
                      [style.color]="user.is_verified_company ? '#0369a1' : '#475569'"
                      [style.border]="user.is_verified_company ? '1px solid #bae6fd' : '1px solid #cbd5e1'"
                      style="padding: 6px 12px; border-radius: 6px; font-size: 13px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 6px;"
                      (click)="onToggleVerification(user)">
                <i class="bi" [ngClass]="user.is_verified_company ? 'bi-patch-check-fill' : 'bi-patch-check'"></i>
                {{ user.is_verified_company ? 'Vérifié' : 'Certifier' }}
              </button>

              <button class="btn-action-delete" (click)="onDeleteUser(user.id)">
                <i class="bi bi-trash3-fill"></i> Supprimer
              </button>
              
            </td>

          </tr>
        </tbody>
      </table>

    </div>
  </div>

  <div *ngIf="showUserCard && selectedUser" class="admin-user-card-overlay" (click)="closeUserCard()">
    <div class="admin-user-card" (click)="$event.stopPropagation()">
      <button class="admin-user-card-close" (click)="closeUserCard()">×</button>
      <div class="admin-user-card-header">
        <div>
          <h4>{{ selectedUser.name }}</h4>
          <p class="admin-user-role">{{ getUserRoleLabel(selectedUser) }}</p>
        </div>
        <span class="admin-badge" [ngClass]="selectedUser.role === 'recruiter' ? (selectedUser.is_verified_company ? 'badge-success' : 'badge-warning') : (selectedUser.is_verified ? 'badge-success' : 'badge-warning')">
          {{ getVerificationLabel(selectedUser) }}
        </span>
      </div>
      <div class="admin-user-card-body">
        <div class="admin-user-field"><span>Adresse e-mail</span><strong>{{ selectedUser.email }}</strong></div>
        <div class="admin-user-field"><span>Rôle</span><strong>{{ getUserRoleLabel(selectedUser) }}</strong></div>
        <div class="admin-user-field"><span>Date d'inscription</span><strong>{{ selectedUser.created_at | date:'dd/MM/yyyy HH:mm' }}</strong></div>
        <div class="admin-user-field" *ngIf="selectedUser.role === 'recruiter'"><span>Statut entreprise</span><strong>{{ selectedUser.is_verified_company ? 'Certifiée' : 'Non certifiée' }}</strong></div>
        <div class="admin-user-field" *ngIf="selectedUser.role !== 'recruiter'"><span>Compte vérifié</span><strong>{{ selectedUser.is_verified ? 'Oui' : 'Non' }}</strong></div>
      </div>
    </div>
  </div>
</div>
